import{_ as e,o as a,c as o,a5 as n}from"./chunks/framework.BjM_ivYE.js";const u=JSON.parse('{"title":"Battery drains on one side","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/battery-one-side.md","filePath":"manual/troubleshooting/battery-one-side.md","lastUpdated":1788840704000}'),r={name:"manual/troubleshooting/battery-one-side.md"};function s(i,t,l,h,c,d){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="battery-drains-on-one-side" tabindex="-1">Battery drains on one side <a class="header-anchor" href="#battery-drains-on-one-side" aria-label="Permalink to &quot;Battery drains on one side&quot;">​</a></h1><h2 id="single-pack-check" tabindex="-1">Check each pack on its own <a class="header-anchor" href="#single-pack-check" aria-label="Permalink to &quot;Check each pack on its own {#single-pack-check}&quot;">​</a></h2><p>To find out whether one pack is faulty, fit <strong>one pack at a time</strong> and check whether the robot powers on.</p><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p><strong>Never stand the robot up or walk it with only one battery pack fitted.</strong> The only thing this check confirms is <strong>whether the robot powers on</strong>. Switch the power off again as soon as you have confirmed it.</p></div></div><ol><li>Put the robot in a <strong>sitting posture</strong> and switch the power off.</li><li>Fit <strong>one battery pack only</strong>.</li><li>Switch the power on and confirm <strong>only that the robot powers up</strong>.</li><li>Switch the power off and remove the pack.</li><li>Fit <strong>the other pack only</strong> and repeat step 3.</li></ol><p>See <a href="/RBQ/manual/maintenance/battery.html">Battery replacement</a> for how to remove and refit the packs.</p><h3 id="result" tabindex="-1">Interpreting the result <a class="header-anchor" href="#result" aria-label="Permalink to &quot;Interpreting the result {#result}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Result</th><th>Meaning</th></tr></thead><tbody><tr><td>Both power on</td><td>Both packs are supplying power correctly</td></tr><tr><td>Only one powers on</td><td>The pack that does not power on, or its connector, has a problem</td></tr><tr><td>Neither powers on</td><td>The cause is something other than the batteries</td></tr></tbody></table><h2 id="voltage-imbalance" tabindex="-1">When the two packs differ significantly in voltage <a class="header-anchor" href="#voltage-imbalance" aria-label="Permalink to &quot;When the two packs differ significantly in voltage {#voltage-imbalance}&quot;">​</a></h2><p>A large voltage gap between the two packs can cause problems. If only one pack powers the robot in the check above, or the symptom returns after swapping packs, stop operating the robot and <a href="/RBQ/manual/support/">contact us</a>.</p><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck? {#still-stuck}&quot;">​</a></h2><p>Tell us the result of the check — whether each pack powered the robot on. <a href="/RBQ/manual/support/">Contact us</a></p><p>For handling precautions, see <a href="/RBQ/manual/safety/battery-handling.html">Battery Handling Precautions</a>.</p>',13)])])}const b=e(r,[["render",s]]);export{u as __pageData,b as default};
